```cpp
void applyNoiseReduction(vector<vector<int>>& frame, int kernelSize) {
    int height = frame.size();
    int width = frame[0].size();
    vector<vector<int>> filtered(height, vector<int>(width, 0));
    for (int i = kernelSize; i < height - kernelSize; i++) {
        for (int j = kernelSize; j < width - kernelSize; j++) {
            int sum = 0;
            for (int di = -kernelSize; di <= kernelSize; di++) {
                for (int dj = -kernelSize; dj <= kernelSize; dj++) {
                    sum += frame[i + di][j + dj];
                }
            }
            filtered[i][j] = sum / ((2 * kernelSize + 1) * (2 * kernelSize + 1));
        }
    }
    frame = filtered;
}
```
