    public List<Stop> prioritizeByProximity(Stop current, List<Stop> remaining) {
        return remaining.stream()
            .sorted((a, b) -> Double.compare(
                calculateDistance(current, a),
                calculateDistance(current, b)))
            .collect(Collectors.toList());
